#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Family {
    /// Appendix-A source family name.
    pub name: &'static str,
    /// Source requirement-id range (e.g. "IDX-01…11").
    pub requirement_ids: &'static str,
    /// Story ids covering the family.
    pub stories: &'static [&'static str],
}

/// Appendix A — coverage traceability from the source requirements inventory.
