impl Story {
    pub fn by_id(id: &str) -> Option<&'static Story> {
        STORIES.iter().find(|s| s.id == id)
    }

    pub fn by_num(num: u16) -> Option<&'static Story> {
        STORIES.iter().find(|s| s.num == num)
    }

    pub fn section_stories(section: &'static str) -> impl Iterator<Item = &'static Story> {
        STORIES.iter().filter(move |s| s.section == section)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalogue_shape_147_contiguous() {
        assert_eq!(STORIES.len(), 147);
        for (i, s) in STORIES.iter().enumerate() {
            assert_eq!(s.num as usize, i + 1);
            assert_eq!(s.id, format!("US-{:03}", i + 1));
        }
    }

    #[test]
    fn catalogue_sections_complete() {
        assert_eq!(SECTIONS.len(), 20);
        let mut seen = 0usize;
        for sec in SECTIONS {
            seen += Story::section_stories(sec).count();
        }
        assert_eq!(seen, 147, "every story belongs to a known section");
    }

    #[test]
    fn catalogue_fields_nonempty_and_actor_parsed() {
        for s in STORIES {
            assert!(!s.title.is_empty() && !s.narrative.is_empty());
            assert!(!s.expected.is_empty() && !s.view.is_empty());
            assert!(!s.actor.is_empty());
            assert!(s.narrative.starts_with("As a ") || s.narrative.starts_with("As an "));
        }
    }

    #[test]
    fn appendix_families_reference_known_stories() {
        assert_eq!(FAMILIES.len(), 28);
        for f in FAMILIES {
            assert!(!f.stories.is_empty(), "{}", f.name);
            for sid in f.stories {
                assert!(Story::by_id(sid).is_some(), "{} -> {}", f.name, sid);
            }
        }
    }

    #[test]
    fn expectations_present() {
        assert_eq!(UNIVERSAL_EXPECTATIONS.len(), 3);
        assert_eq!(ACCEPTANCE_EXPECTATIONS.len(), 9);
    }
}
